contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function test(uint256 amount) public {
        c.AdjustBetAmounts(amount); if (__ESBMC_reverted()) return;
        assert(c.currentBetLimit() == amount);
    }
    receive() external payable {}
    fallback() external payable {}
}

